"""Write docs/API.md from the header comment of each api/*.js (the header is the contract).
Run: python3 tools/gen_api_doc.py"""
import os, glob
base = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
out = ['# API contracts', '',
       '_Generated by `python3 tools/gen_api_doc.py` from the header comment of each `api/*.js`. Do not edit by hand:',
       'change the header in the endpoint file and regenerate._', '']
for f in sorted(glob.glob(os.path.join(base, 'api', '*.js'))):
    head = []
    for line in open(f, encoding='utf-8'):
        if not line.startswith('//'): break
        head.append(line.rstrip('\n'))
    out += ['## api/' + os.path.basename(f), '```'] + head + ['```', '']
open(os.path.join(base, 'docs', 'API.md'), 'w', encoding='utf-8').write('\n'.join(out))
print('docs/API.md written,', len(out), 'lines')
